-- docs/AUDIT-2026-09-13.md §2 L-8: every post-call webhook carries X-RobotCall-Delivery, an
-- id that stays the same across the delivery's retries so a receiver can drop a duplicate.
-- The first try is made before the row exists, so the id is generated by the application
-- and stored with the row; rows already waiting for a retry get one here.
ALTER TABLE webhook_delivery ADD COLUMN delivery_id UUID NOT NULL DEFAULT gen_random_uuid();
